export namespace Effect {
  export interface Effect<A, E = never, R = never> {
    readonly _A: A
    readonly _E: E
    readonly _R: R
  }
}
export namespace Stream {
  export interface Stream<A, E = never, R = never> {
    readonly _A: A
    readonly _E: E
    readonly _R: R
  }
}
export namespace Cause {
  export interface Cause<E> { readonly _E: E }
}
export const Effect: {
  catchCause<A, E, R, A2, E2, R2>(self: Effect.Effect<A, E, R>, handler: (cause: Cause.Cause<E>) => Effect.Effect<A2, E2, R2>): Effect.Effect<A | A2, E2, R | R2>
  catchCause<E, A2, E2, R2>(handler: (cause: Cause.Cause<E>) => Effect.Effect<A2, E2, R2>): <A, R>(self: Effect.Effect<A, E, R>) => Effect.Effect<A | A2, E2, R2 | R>
  succeed<A>(value: A): Effect.Effect<A>
  failCause<E>(cause: Cause.Cause<E>): Effect.Effect<never, E>
  logError(cause: unknown): Effect.Effect<void>
  andThen<A, E, R, A2, E2, R2>(first: Effect.Effect<A, E, R>, second: Effect.Effect<A2, E2, R2>): Effect.Effect<A2, E | E2, R | R2>
}
export const Stream: {
  catchCause<A, E, R, A2, E2, R2>(self: Stream.Stream<A, E, R>, handler: (cause: Cause.Cause<E>) => Stream.Stream<A2, E2, R2>): Stream.Stream<A | A2, E2, R | R2>
  failCause<E>(cause: Cause.Cause<E>): Stream.Stream<never, E>
}
